import functools
import time
from typing import Callable, Type, Tuple, Optional

def retry(max_attempts: int,
          delay: float,
          exceptions: Tuple[type, ...] = (Exception,)
          ) -> Callable[[Callable[..., Any]], Callable[..., Any]:
    """
    Decorator that retries a function call a specified number of times
    if it raises any of the given exception types.
    """
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc: Optional[Type[BaseException]] = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < max_attempts:
                        time.sleep(delay)
                    # else: stop after max_attempts, will raise later
            raise last_exc
        return wrapper
    return decorator

# Example usage:
